/**
 * The types `data/relics/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    RelicTemplate, RelicUnlockMethodKey, RelicUnlockMethodDefinition, RelicBonusTotalRow, RelicBonusCategoryKey, RelicBonusCategoryDefinition
 * depends    —
 * used by    src/data/relics/data, src/data/relics/index, src/save/catalogs/relic-template-match
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from data.ts

export type RelicTemplate = {
  id: string
  name: string
  description?: string
  requirement?: string
  icon?: string
  bonusType?: string
  value?: string
  rarity?: string
  event?: string
  type?: string
}

export type RelicUnlockMethodKey =
  | 'milestone_wave_4500'
  | 'tournament_placement'
  | 'event_completion'
  | 'event_rerun_store'
  | 'guild_store'
  | 'years_of_gameplay'

export interface RelicUnlockMethodDefinition {
  key: RelicUnlockMethodKey
  label: string
  description: string
}

export interface RelicBonusTotalRow {
  stat: string
  total: string
}

export type RelicBonusCategoryKey = 'misc' | 'damage' | 'defense' | 'utility'

export interface RelicBonusCategoryDefinition {
  key: RelicBonusCategoryKey
  label: string
  description: string
  rows: readonly RelicBonusTotalRow[]
}
